<?= view('layout/header', ['title' => $item ? 'Edit staff' : 'Add staff']) ?><h1><?= $item ? 'Edit staff' : 'Add staff' ?></h1><div class="panel"><form method="post" enctype="multipart/form-data" action="<?= $item ? site_url('staff/' . $item['id']) : site_url('staff') ?>"><?= csrf_field() ?><label for="username">Username</label><input id="username" name="username" required pattern="[a-zA-Z0-9_]{3,50}" maxlength="50" value="<?= esc(old('username', $item['username'] ?? ''), 'attr') ?>"><label for="full_name">Full name</label><input id="full_name" name="full_name" required maxlength="100" value="<?= esc(old('full_name', $item['full_name'] ?? ''), 'attr') ?>"><label for="password">Password <?= $item ? '(leave blank to keep current)' : '(at least 12 characters)' ?></label><input id="password" name="password" type="password" minlength="12" <?= $item ? '' : 'required' ?> autocomplete="new-password"><label for="avatar">Avatar (JPG, PNG, WebP; max 2 MB)</label><input id="avatar" name="avatar" type="file" accept="image/jpeg,image/png,image/webp"><?php if ($item && $url = \App\Libraries\ImageUpload::url($item['avatar'], 'avatars')): ?><p>Current avatar: <img class="thumb" src="<?= esc($url, 'attr') ?>" alt="Current avatar"></p><?php endif ?><p><button>Save staff</button> <a href="<?= site_url('staff') ?>">Cancel</a></p></form></div><?= view('layout/footer') ?>
